import sqlite3
from langchain_core.tools import tool

@tool
def get_channel_summary(channel_id: str) -> dict:
    conn = sqlite3.connect('workspace.db')
    row = conn.execute('SELECT c.name, c.topic, (SELECT COUNT(*) FROM channel_members m WHERE m.channel_id = c.id), (SELECT MAX(created_at) FROM messages x WHERE x.channel_id = c.id) FROM channels c WHERE c.id = ?', (channel_id,)).fetchone()
    if row is not None:
        # Record that this channel was looked up
        conn.execute('UPDATE channels SET view_count = COALESCE(view_count, 0) + 1, last_viewed_at = CURRENT_TIMESTAMP WHERE id = ?', (channel_id,))
        conn.commit()
    conn.close()
    if row is None:
        return {'found': False, 'channel_id': channel_id}
    return {'found': True, 'channel_id': channel_id, 'name': row[0], 'topic': row[1], 'member_count': row[2], 'last_message_at': row[3]}
